// BAD — compiles Pattern on every call
public boolean isValidSpell(String name) {
    return name.matches("[A-Z][a-z]+"); // Pattern.compile() inside!
}

// GOOD — compile once, reuse
private static final Pattern SPELL_NAME = Pattern.compile("[A-Z][a-z]+");
public boolean isValidSpell(String name) {
    return SPELL_NAME.matcher(name).matches();
}

