import java.util.regex.Pattern;

public class PerfDemo {
    private static final Pattern NAME_PATTERN = Pattern.compile("[A-Z][a-z]+");

    static String concatBad() {
        String s = "";
        for (int i = 0; i < 50; i++) s += i;
        return s;
    }

    static String concatGood() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 50; i++) sb.append(i);
        return sb.toString();
    }

    static boolean matchBad(String s)  { return s.matches("[A-Z][a-z]+"); }
    static boolean matchGood(String s) { return NAME_PATTERN.matcher(s).matches(); }

    public static void main(String[] args) {
        for (int i = 0; i < 10_000; i++) { concatBad(); concatGood(); }
        long s1 = System.nanoTime();
        for (int i = 0; i < 100_000; i++) concatBad();
        long s2 = System.nanoTime();
        for (int i = 0; i < 100_000; i++) concatGood();
        long s3 = System.nanoTime();
        System.out.println("ConcatBad ns:  " + (s2 - s1));
        System.out.println("ConcatGood ns: " + (s3 - s2));
        System.out.println("matchBad:  " + matchBad("Fireball"));
        System.out.println("matchGood: " + matchGood("Fireball"));
    }
}

