public class BoxingPerf {
    static long sumBoxed(int n) {
        Integer acc = 0;
        for (int i = 0; i < n; i++) acc += i; // auto-unbox + box each iteration
        return acc;
    }
    static long sumPrimitive(int n) {
        long acc = 0;
        for (int i = 0; i < n; i++) acc += i;
        return acc;
    }
    public static void main(String[] args) {
        for (int i = 0; i < 10_000; i++) { sumBoxed(1000); sumPrimitive(1000); }
        long s1 = System.nanoTime();
        long rb = 0; for (int i = 0; i < 1_000_000; i++) rb = sumBoxed(1000);
        long s2 = System.nanoTime();
        long rp = 0; for (int i = 0; i < 1_000_000; i++) rp = sumPrimitive(1000);
        long s3 = System.nanoTime();
        System.out.println("Boxed result:     " + rb + " in " + (s2-s1)/1_000_000 + "ms");
        System.out.println("Primitive result: " + rp + " in " + (s3-s2)/1_000_000 + "ms");
        System.out.println("499500");
        System.out.println("boxed allocates per addition; primitive does not");
    }
}
